export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;
  const t = time;

  const v = u - g * t;
  const y = u * t - 0.5 * g * t * t;
  const a = -g;
  const F = m * g;

  const apexTime = u / g;
  const apexHeight = (u * u) / (2 * g);

  let motionState = "Ready to toss";
  if (t > 0 && t < apexTime) {
    motionState = "Rising";
  } else if (Math.abs(t - apexTime) < 0.02) {
    motionState = "At the top";
  } else if (t > apexTime && y >= 0) {
    motionState = "Falling";
  } else if (y < 0) {
    motionState = "Back at launch height";
  }

  const laneLeft = sdk.panel({
    x: 30,
    y: 35,
    w: 280,
    h: 360,
    title: "Motion",
    state: motionState,
    id: "lane.motion"
  });

  const axisY = sdk.axis("axis.height", {
    x: 70,
    y: 340,
    length: 240,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  });

  const ballYCoord = 340 - (y / 2.2) * 240;
  const ballObj = sdk.circle("ball.toss", 140, ballYCoord, 24, {
    role: "output"
  });

  const vecV = sdk.vector(
    "vec.v",
    { x: 180, y: ballYCoord },
    { value: v, direction: "up" },
    { scale: 15, label: "v" }
  );

  const vecA = sdk.vector(
    "vec.a",
    { x: 215, y: ballYCoord },
    { value: a, direction: "up" },
    { scale: 15, label: "a" }
  );

  const calloutObj = sdk.callout(
    235,
    ballYCoord - 20,
    [
      `v: ${v.toFixed(2)} m/s`,
      `a: ${a.toFixed(2)} m/s^2`,
      `Fg: ${F.toFixed(1)} N`
    ],
    { id: "callout.toss" }
  );

  const points = [];
  const steps = 20;
  for (let i = 0; i <= steps; i++) {
    const ti = (i / steps) * (2 * apexTime);
    const vi = u - g * ti;
    points.push([ti, vi]);
  }

  const currentPt = [t, v];

  const plotObj = sdk.plot("plot.vt", {
    x: 330,
    y: 35,
    w: 280,
    h: 360,
    axes: {
      x: { label: "Time", min: 0, max: 1.8, unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      {
        label: "v(t)",
        kind: "line",
        points: points
      },
      {
        label: "Current",
        kind: "scatter",
        points: [currentPt]
      }
    ]
  });

  const noteObj = sdk.text(
    "plot.vt.note",
    350,
    375,
    `Slope a = -g = ${a.toFixed(1)} m/s^2`,
    { role: "neutral" }
  );

  const objects = [
    ...laneLeft,
    axisY,
    ballObj,
    ...vecV,
    ...vecA,
    ...calloutObj,
    plotObj,
    noteObj
  ];

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "velocity", value: Number(v.toFixed(2)) },
        { id: "acceleration", value: Number(a.toFixed(2)) },
        { id: "force", value: Number(F.toFixed(2)) },
        { id: "motionState", value: motionState }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime,
      apexHeight,
      height: y,
      velocity: v,
      acceleration: a,
      force: F
    }
  };
}
